llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Pethidine, a small ionizable amine with an aromatic ring and ester, has absolute oral bioavailability of 0.61 in healthy volunteers, supporting that a moderately polar small molecule can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Maraviroc, a larger polar drug with amide and basic amine functionalities, has absolute oral bioavailability of 23.1% in humans, directly above the 20% threshold and supporting high bioavailability for a molecule with multiple polar groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ampicillin, a carboxylic-acid-containing drug with an aromatic side chain, has absolute oral bioavailability of about 40% in humans, showing that an ionized carboxylic acid does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Perindopril, an ACE inhibitor with a proline-like core and carboxylic acid, has absolute oral bioavailability of 65–75%, supporting high bioavailability for the query's ACE-inhibitor-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Felbamate, a small polar carbamate with an aromatic ring, has oral bioavailability greater than 90%, supporting that the query's combination of polar groups and aromatic ring is compatible with high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability at or above 20%, mostly well above the threshold. The query's carboxylic acid, thiol, and phenylthio features are represented among these high-F compounds, so high bioavailability is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for zofenoprilat itself; extrapolation relies on close analogues with high F.",
    "The active-metabolite analogue perindoprilat was only assessed after prodrug administration, not as the orally administered molecule, so it does not provide affirmative low-bioavailability evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

